const listTrash = `-- name: ListTrash :many
SELECT p.id, p.created_by, p.title, p.parent_id, p.path::text AS path, p.sort_key,
       p.lifecycle_state, p.deleted_at, p.created_at, p.updated_at,
       (p.deleted_at + $3::interval)::timestamptz AS purge_at,
       d.steps_done, d.attempts, d.last_error, d.completed_at
FROM docs.pages p
LEFT JOIN docs.page_deletions d ON d.page_id = p.id
WHERE p.deleted_at IS NOT NULL
ORDER BY p.deleted_at DESC
LIMIT $1 OFFSET $2
`

type ListTrashParams struct {
	Limit       int32
	Offset      int32
	PurgeWindow pgtype.Interval
}

type ListTrashRow struct {
	ID             pgtype.UUID
	CreatedBy      pgtype.UUID
	Title          string
	ParentID       pgtype.UUID
	Path           string
	SortKey        string
	LifecycleState string
	DeletedAt      pgtype.Timestamptz
	CreatedAt      pgtype.Timestamptz
	UpdatedAt      pgtype.Timestamptz
	PurgeAt        pgtype.Timestamptz
	StepsDone      []string
	Attempts       *int32
	LastError      *string
	CompletedAt    pgtype.Timestamptz
}

// Both terminal-ish states, newest first: 'deleting' (saga in flight) and
// 'deleted' (restorable until purge). purge_at is derived from deleted_at
// at read time rather than stored, so changing the window moves every
// pending purge without a backfill (DATA_MODEL.md § Page deletions).
func (q *Queries) ListTrash(ctx context.Context, arg ListTrashParams) ([]ListTrashRow, error) {
	rows, err := q.db.Query(ctx, listTrash, arg.Limit, arg.Offset, arg.PurgeWindow)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListTrashRow
	for rows.Next() {
		var i ListTrashRow
		if err := rows.Scan(
			&i.ID,
			&i.CreatedBy,
			&i.Title,
			&i.ParentID,
			&i.Path,
			&i.SortKey,
			&i.LifecycleState,
			&i.DeletedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.PurgeAt,
			&i.StepsDone,
			&i.Attempts,
			&i.LastError,
			&i.CompletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const nextSiblingSortKey = `-- name: NextSiblingSortKey :one
SELECT sort_key FROM docs.pages
WHERE deleted_at IS NULL
  AND (parent_id = $1 OR (parent_id IS NULL AND $1 IS NULL))
  AND sort_key > $2::text
  AND ($3::uuid IS NULL OR id != $3)
ORDER BY sort_key ASC
LIMIT 1
`

type NextSiblingSortKeyParams struct {
	ParentID     pgtype.UUID
	AfterSortKey string
	ExcludeID    pgtype.UUID
}

// The sibling immediately after afterSortKey under the same parent (NULL
// parent_id means root pages) — used to bound a new page's fractional
// sort_key from above when it's inserted after a specific sibling.
// exclude_id skips the page being moved itself, for ReparentPage's
// reorder-within-the-same-parent case; Create passes it NULL.
func (q *Queries) NextSiblingSortKey(ctx context.Context, arg NextSiblingSortKeyParams) (string, error) {
	row := q.db.QueryRow(ctx, nextSiblingSortKey, arg.ParentID, arg.AfterSortKey, arg.ExcludeID)
	var sort_key string
	err := row.Scan(&sort_key)
	return sort_key, err
}

const pageStatsFor = `-- name: PageStatsFor :many
SELECT b.page_id,
       COUNT(*)::int AS block_count,
       COALESCE(SUM(
         CASE
           WHEN trim(coalesce(b.content->>'text', '')) = '' THEN 0
           ELSE array_length(regexp_split_to_array(trim(b.content->>'text'), '\s+'), 1)
         END
       ), 0)::int AS word_count
FROM docs.blocks b
WHERE b.page_id = ANY($1::uuid[])
GROUP BY b.page_id
`

type PageStatsForRow struct {
	PageID     pgtype.UUID
	BlockCount int32
	WordCount  int32
}

// Block and word counts per page, over the docs.blocks projection.
//
// Counted HERE rather than in the browser for the same reason every other
// figure in this app is: the reader, the page tree, the dashboard and search
// all print a reading estimate, and four client-side word counts over four
// differently-shaped payloads is four numbers that disagree. Postgres already
// holds the text.
//
// Batched over an array, like ClassificationFor — ListPages decorates 50 rows
// at a time and a per-row query would be the N+1 that avoids.
//
// A block whose text is empty (a divider, an empty list container) counts as
// zero words but still as a block: it is structure, and the block count is
// how much structure there is.
func (q *Queries) PageStatsFor(ctx context.Context, pageIds []pgtype.UUID) ([]PageStatsForRow, error) {
	rows, err := q.db.Query(ctx, pageStatsFor, pageIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PageStatsForRow
	for rows.Next() {
		var i PageStatsForRow
		if err := rows.Scan(&i.PageID, &i.BlockCount, &i.WordCount); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const recordPageDeletionFailure = `-- name: RecordPageDeletionFailure :exec
UPDATE docs.page_deletions
SET last_error = $1, attempts = attempts + 1, updated_at = NOW()
WHERE page_id = $2
`

type RecordPageDeletionFailureParams struct {
	LastError *string
	PageID    pgtype.UUID
}

// Forward-only compensation: a failing step is recorded and retried, never
// rolled back. attempts is bumped here rather than at claim time so it
// counts real resumptions, not sweeps that found nothing to do.
func (q *Queries) RecordPageDeletionFailure(ctx context.Context, arg RecordPageDeletionFailureParams) error {
	_, err := q.db.Exec(ctx, recordPageDeletionFailure, arg.LastError, arg.PageID)
	return err
}

const recordPageDeletionStep = `-- name: RecordPageDeletionStep :exec
UPDATE docs.page_deletions
SET steps_done = CASE WHEN $1::text = ANY(steps_done)
                      THEN steps_done
                      ELSE array_append(steps_done, $1::text) END,
    last_error = NULL,
    updated_at = NOW()
WHERE page_id = $2
`

type RecordPageDeletionStepParams struct {
	Step   string
	PageID pgtype.UUID
}

// Appends one completed step. array_append is guarded by NOT (... = ANY ...)
// so re-running a step that already recorded itself is a no-op rather than a
// duplicate entry — steps_done is a set that happens to keep its order.
func (q *Queries) RecordPageDeletionStep(ctx context.Context, arg RecordPageDeletionStepParams) error {
	_, err := q.db.Exec(ctx, recordPageDeletionStep, arg.Step, arg.PageID)
	return err
}

