const reparentPageRow = `-- name: ReparentPageRow :one
UPDATE docs.pages
SET parent_id = $1, path = $2::ltree, sort_key = $3, updated_at = NOW()
WHERE id = $4 AND deleted_at IS NULL
RETURNING id, created_by, title, parent_id, path::text AS path, sort_key,
          lifecycle_state, deleted_at, created_at, updated_at
`

type ReparentPageRowParams struct {
	ParentID pgtype.UUID
	Path     string
	SortKey  string
	ID       pgtype.UUID
}

type ReparentPageRowRow struct {
	ID             pgtype.UUID
	CreatedBy      pgtype.UUID
	Title          string
	ParentID       pgtype.UUID
	Path           string
	SortKey        string
	LifecycleState string
	DeletedAt      pgtype.Timestamptz
	CreatedAt      pgtype.Timestamptz
	UpdatedAt      pgtype.Timestamptz
}

// Moves a single page: new parent (nullable — NULL promotes it to root),
// new path, new sort_key. Descendants' paths are a separate statement
// (RewriteDescendantPaths) — both run in the same transaction
// (internal/pages's Reparent), so a concurrent reader sees all old paths
// or all new ones, never a mixture (docs/api/pages.md § Reparent).
// No owner scoping — see GetPage.
func (q *Queries) ReparentPageRow(ctx context.Context, arg ReparentPageRowParams) (ReparentPageRowRow, error) {
	row := q.db.QueryRow(ctx, reparentPageRow,
		arg.ParentID,
		arg.Path,
		arg.SortKey,
		arg.ID,
	)
	var i ReparentPageRowRow
	err := row.Scan(
		&i.ID,
		&i.CreatedBy,
		&i.Title,
		&i.ParentID,
		&i.Path,
		&i.SortKey,
		&i.LifecycleState,
		&i.DeletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const restorePageAndSubtree = `-- name: RestorePageAndSubtree :execrows
UPDATE docs.pages p
SET lifecycle_state = 'active', deleted_at = NULL, updated_at = NOW()
FROM docs.pages target
WHERE target.id = $1
  AND target.lifecycle_state = 'deleted'
  AND (p.id = target.id OR (p.path <@ target.path AND p.deleted_at = target.deleted_at))
`

// Restore is the inverse of StepTreeDetached and nothing else — the later
// steps are not undone, they are re-derived: page_links and the FTS index
// are projections that rebuild from the op log, and the op log was sealed,
// never deleted. Scoped to rows deleted in the SAME saga (deleted_at equal
// to the target's) so restoring a page does not resurrect a child that was
// already in the trash on its own before this delete ran.
func (q *Queries) RestorePageAndSubtree(ctx context.Context, pageID pgtype.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, restorePageAndSubtree, pageID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const rewriteDescendantPaths = `-- name: RewriteDescendantPaths :execrows
UPDATE docs.pages
SET path = $1::ltree || subpath(path, nlevel($2::ltree)),
    updated_at = NOW()
WHERE path <@ $2::ltree AND id != $3
`

type RewriteDescendantPathsParams struct {
	NewPrefix string
	OldPrefix string
	PageID    pgtype.UUID
}

// Replaces the old_prefix ancestry on every descendant of the page being
// moved with new_prefix, preserving each descendant's own trailing labels.
// subpath(path, nlevel(old_prefix)) strips exactly the old ancestor
// portion off the front of each descendant's path.
func (q *Queries) RewriteDescendantPaths(ctx context.Context, arg RewriteDescendantPathsParams) (int64, error) {
	result, err := q.db.Exec(ctx, rewriteDescendantPaths, arg.NewPrefix, arg.OldPrefix, arg.PageID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const saveReadingPosition = `-- name: SaveReadingPosition :exec
INSERT INTO docs.reading_positions (user_id, page_id, block_id, caret_start, caret_end, updated_at)
VALUES ($1, $2, $3, $4, $5, NOW())
ON CONFLICT (user_id, page_id) DO UPDATE
SET block_id    = EXCLUDED.block_id,
    caret_start = EXCLUDED.caret_start,
    caret_end   = EXCLUDED.caret_end,
    updated_at  = NOW()
`

type SaveReadingPositionParams struct {
	UserID     pgtype.UUID
	PageID     pgtype.UUID
	BlockID    pgtype.UUID
	CaretStart int32
	CaretEnd   int32
}

// Upsert: one row per (user, page). Writing a position for a page the user
// cannot see is impossible here only because every page is visible at this
// repo's scope — when RBAC lands (v3.1.0) this needs the same can_apply
// check every other write goes through.
func (q *Queries) SaveReadingPosition(ctx context.Context, arg SaveReadingPositionParams) error {
	_, err := q.db.Exec(ctx, saveReadingPosition,
		arg.UserID,
		arg.PageID,
		arg.BlockID,
		arg.CaretStart,
		arg.CaretEnd,
	)
	return err
}

